descriptor.templateCss:
.samsung-menu-widget {
    display: flex;
    height: 100%;
    font-family: Arial, sans-serif;
}

/* Left Sidebar Styling */
.sidebar {
    background-color: #1e3a5f;
    /* Dark blue background */
    width: 25%;
    padding: 20px;
    box-sizing: border-box;
    color: #fff;
}

.sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar li {
    padding: 10px;
    cursor: pointer;
    border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

/* Right Main Content Styling */
.menu-content {
    flex: 1;
    background-color: #f0f8ff;
    /* Light blue background */
    padding: 20px;
    box-sizing: border-box;
}

.menu-content h2 {
    color: #1e3a5f;
    margin-bottom: 15px;
}

descriptor.controllerScript:
self.onInit = function() {
    // Define the menu points (sections)
    self.ctx.$scope.sections = [{
            name: 'Home'
        },
        {
            name: 'News'
        },
        {
            name: 'Settings'
        },
        {
            name: 'About'
        }
    ];


};
